; ---- if ( steer[axisX].vel != 0 ) star[i].x -= ( steer[axisX].vel * zi ) >> 2
        mov     ax, [steer__vel]
        test    ax, ax
        je      .L68                        ; signed !=
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__x + bx]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [steer__vel]
        mov     bx, [moveStar__zi]
        mul     bx                          ; low 16 bits are sign-agnostic
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        sub     ax, bx
        mov     bx, [moveStar__i]
        shl     bx, 1                       ; word elements
        mov     [star__x + bx], ax
.L68:
; ---- if ( steer[axisY].vel != 0 ) star[i].y -= ( steer[axisY].vel * zi ) >> 2
        mov     ax, [steer__vel + 2]
        test    ax, ax
        je      .L71                        ; signed !=
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__y + bx]
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [steer__vel + 2]
        mov     bx, [moveStar__zi]
        mul     bx                          ; low 16 bits are sign-agnostic
        sar     ax, 1                       ; signed >>
        sar     ax, 1
        mov     bx, ax
        pop     ax
        sub     ax, bx
        mov     bx, [moveStar__i]
        shl     bx, 1                       ; word elements
        mov     [star__y + bx], ax
.L71:
; ---- sx = centreX + star[i].x / zi
        mov     ax, 160
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__x + bx]
        mov     bx, [moveStar__zi]
        cwd                                 ; sign-extend AX into DX:AX
        idiv    bx
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [moveStar__sx], ax
; ---- sy = centreY + star[i].y / zi
        mov     ax, 100
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__y + bx]
        mov     bx, [moveStar__zi]
        cwd                                 ; sign-extend AX into DX:AX
        idiv    bx
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [moveStar__sy], ax
; ---- if ( u16( sx ) >= screenW || u16( sy ) >= screenH ) {
        mov     ax, [moveStar__sx]
        cmp     ax, 320
        jae     .L76                        ; unsigned >=
        mov     ax, [moveStar__sy]
        cmp     ax, 200
        jb      .L74                        ; unsigned >=
.L76:
; ---- respawn( i )
        mov     ax, [moveStar__i]
        mov     [respawn__i], ax
        call    respawn
; ---- return
        ret
.L74:
; ---- off = u16( sy ) * screenW + u16( sx )
        mov     ax, [moveStar__sy]
        mov     bx, 320
        mul     bx                          ; low 16 bits are sign-agnostic
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moveStar__sx]
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [moveStar__off], ax
; ---- if ( off != star[i].off ) erase( i )
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__off + bx]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        je      .L79                        ; unsigned !=
        mov     ax, [moveStar__i]
        mov     [erase__i], ax
        call    erase
.L79:
; ---- pixels[off] = shadeOf( star[i].z )
        mov     ax, 16
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moveStar__i]
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [star__z + bx]
        mov     bx, 192
        xor     dx, dx                      ; clear high half for div
        div     bx
        xor     ah, ah                      ; cast to u8
        mov     bx, ax
        pop     ax
        sub     ax, bx
        xor     ah, ah                      ; cast to u8
        mov     bx, [moveStar__off]
        mov     dx, 0xA000                  ; segment of pixels
        mov     es, dx
        mov     [es:bx], al
; ---- star[i].off = off
        mov     ax, [moveStar__off]
        mov     bx, [moveStar__i]
        shl     bx, 1                       ; word elements
        mov     [star__off + bx], ax
        ret

; ============================================== sub readKeys ====

readKeys:
; ---- while ( keyPending() ) {
.L82:
        call    keyPending
        mov     al, [keyPending__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jnz     .L85
        jmp     .L84
.L85:
; ---- k = keyNorm( readKeyEx(), 0 )
        call    readKeyEx
        mov     ax, [readKeyEx__ret]
        push    ax                          ; argument evaluated before any is stored
        mov     word [keyNorm__flags], 0
        pop     ax
        mov     [keyNorm__ax], ax
        call    keyNorm
        mov     ax, [keyNorm__ret]
        mov     [readKeys__k], ax
; ---- if ( k == keyEsc ) running = false
        cmp     ax, 27
        jne     .L86                        ; unsigned ==
        mov     byte [running], 0
        jmp     .L87
.L86:
; ---- else if ( k == keyExt + keyLeft ) push( axisX, -1 )
        mov     ax, [readKeys__k]
        cmp     ax, 331
        jne     .L89                        ; unsigned ==
        mov     byte [push__a], 0
        mov     word [push__dir], 65535
        call    push
        jmp     .L90
.L89:
; ---- else if ( k == keyExt + keyRight ) push( axisX, 1 )
        mov     ax, [readKeys__k]
        cmp     ax, 333
        jne     .L92                        ; unsigned ==
        mov     byte [push__a], 0
        mov     word [push__dir], 1
        call    push
        jmp     .L93
.L92:
; ---- else if ( k == keyExt + keyUp ) push( axisY, -1 )
        mov     ax, [readKeys__k]
        cmp     ax, 328
        jne     .L95                        ; unsigned ==
        mov     byte [push__a], 1
        mov     word [push__dir], 65535
        call    push
        jmp     .L96
.L95:
; ---- else if ( k == keyExt + keyDown ) push( axisY, 1 )
        mov     ax, [readKeys__k]
        cmp     ax, 336
        jne     .L98                        ; unsigned ==
        mov     byte [push__a], 1
        mov     word [push__dir], 1
        call    push
        jmp     .L99
.L98:
; ---- else if ( k == '+' || k == '=' ) {
        mov     ax, [readKeys__k]
        cmp     ax, 43
        je      .L103                       ; unsigned ==
        mov     ax, [readKeys__k]
        cmp     ax, 61
        jne     .L101                       ; unsigned ==
.L103:
; ---- if ( speed < len( speeds ) - 1 ) speed++
        mov     al, [speed]
        cmp     al, 12                      ; byte operands, no widening
        jae     .L106                       ; unsigned <
        inc     byte [speed]
.L106:
        jmp     .L102
.L101:
; ---- } else if ( k == '-' || k == '_' ) {
        mov     ax, [readKeys__k]
        cmp     ax, 45
        je      .L111                       ; unsigned ==
        mov     ax, [readKeys__k]
        cmp     ax, 95
        jne     .L109                       ; unsigned ==
.L111:
; ---- if ( speed > 0 ) speed--
        mov     al, [speed]
        test    al, al
        jbe     .L114                       ; unsigned >
        dec     byte [speed]
.L114:
.L109:
.L102:
.L99:
.L96:
.L93:
.L90:
.L87:
.L83:
        jmp     .L82
.L84:
        ret

; ============================================== bool inRetrace ====

inRetrace:
; ---- bool inRetrace() => ( in8( vgaStatus ) & vgaVRetrace ) != 0
        mov     dx, 986
        in      al, dx
        xor     ah, ah                      ; u8 -> u16
        and     ax, 8
        test    ax, ax
        je      .L117                       ; unsigned !=
        mov     ax, 1
        jmp     .L118
.L117:
        xor     ax, ax
.L118:
        mov     [inRetrace__ret], al        ; narrowed to bool
        ret

; ============================================== sub waitRetrace ====

waitRetrace:
; ---- while ( inRetrace() ) {
.L120:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L122
.L121:
        jmp     .L120
.L122:
; ---- while ( !inRetrace() ) {
.L124:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jnz     .L126
.L125:
        jmp     .L124
.L126:
        ret

; ============================================== sub frame ====

frame:
; ---- for ( u16 i = 0; i < starCount; i++ ) moveStar( i )
        mov     word [frame__i], 0
.L128:
        mov     ax, [frame__i]
        cmp     ax, 112
        jae     .L130                       ; unsigned <
        mov     ax, [frame__i]
        mov     [moveStar__i], ax
        call    moveStar
.L129:
        inc     word [frame__i]
        jmp     .L128
.L130:
; ---- readKeys()
        call    readKeys
; ---- glide( axisX )
        mov     byte [glide__a], 0
        call    glide
; ---- glide( axisY )
        mov     byte [glide__a], 1
        call    glide
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int16:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0

; ---- variables ----
i:              dw      0        ; u16
keyPending__ret: db      0        ; bool
readKeyEx__ret: dw      0        ; u16
keyNorm__ax:    dw      0        ; u16
keyNorm__flags: dw      0        ; u16
keyNorm__ret:   dw      0        ; u16
mode__curW:     dw      0        ; u16
mode__curH:     dw      0        ; u16
mode__curElems: dw      0        ; u16
mode__curSeg:   dw      0        ; u16
mode__curElemBytes: db      0        ; u8
mode__isTextMode__m: db      0        ; u8
mode__isTextMode__ret: db      0        ; bool
mode__savedMode: db      0        ; u8
mode__savedRows: dw      0        ; u16
setMode__id:    db      0        ; u8
setDac__index:  db      0        ; u8
setDac__r:      db      0        ; u8
setDac__g:      db      0        ; u8
setDac__b:      db      0        ; u8
rand__randomSeed: dw      42        ; u16 = 42
seedRandom__s:  dw      0        ; u16
nextRandom__ret: dw      0        ; u16
randomBelow__n: dw      0        ; u16
randomBelow__ret: dw      0        ; u16
ticks__ret:     dw      0        ; u16
spawn__i:       dw      0        ; u16
spawn__z:       dw      0        ; u16
speed:          db      5        ; u8 = 5
push__a:        db      0        ; u8
push__dir:      dw      0        ; i16
glide__a:       db      0        ; u8
erase__i:       dw      0        ; u16
respawn__i:     dw      0        ; u16
moveStar__i:    dw      0        ; u16
running:        db      1        ; bool = 1
inRetrace__ret: db      0        ; bool
keyNorm__low:   dw      0        ; u16
keyNorm__scan:  dw      0        ; u16
loadShades__s:  db      0        ; u8
moveStar__zi:   dw      0        ; i16
moveStar__sx:   dw      0        ; i16
moveStar__sy:   dw      0        ; i16
moveStar__off:  dw      0        ; u16
readKeys__k:    dw      0        ; u16
frame__i:       dw      0        ; u16

; ---- arrays ----
screenMode__bios: db      3, 3, 19        ; u8[3]
screenMode__smallFont: db      0, 1, 0        ; u8[3]
screenMode__nomW: dw      0, 0, 320        ; u16[3]
screenMode__nomH: dw      0, 0, 200        ; u16[3]
screenMode__seg: dw      47104, 47104, 40960        ; u16[3]
screenMode__elemBytes: db      2, 2, 1        ; u8[3]
star__x:        times 112 dw 0        ; i16[112]
star__y:        times 112 dw 0        ; i16[112]
star__z:        times 112 dw 0        ; u16[112]
star__off:      times 112 dw 0        ; u16[112]
speeds:         dw      2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128        ; u16[13] const
steer__vel:     times 2 dw 0        ; i16[2]
steer__dir:     times 2 dw 0        ; i16[2]
steer__hold:    times 2 db 0        ; u8[2]

; ============================================================ heap ====
; No storage is emitted - a .COM owns everything past its image, so
; these are addresses and NASM does the arithmetic.

_hstack:        equ     278        ; 22 worst-case + 256 interrupt reserve
_htop:          equ     0FFFEh - _hstack

_hsize:         dw      _htop - _heap        ; NASM computes this
        align   2                           ; keep the u16 view aligned
_heap:
_heapw:         equ     _heap        ; same bytes, u16 view
